dashboard.definition:
{
  "title": "Config sync",
  "description": "Configuration status of devices as reported by New Central, with local changes and admin logins from syslog.",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "tr",
        "defaultValue": "-24h,now"
      }
    },
    "input_site": {
      "type": "input.text",
      "title": "Site (wildcard)",
      "options": {
        "token": "site",
        "defaultValue": "*"
      }
    },
    "input_cfg": {
      "type": "input.dropdown",
      "title": "Config status",
      "options": {
        "token": "cfg",
        "defaultValue": "*",
        "items": [
          {
            "label": "All",
            "value": "*"
          },
          {
            "label": "Out of sync",
            "value": "Out of sync"
          },
          {
            "label": "Synchronized",
            "value": "Synchronized"
          },
          {
            "label": "Not reported",
            "value": "(not reported)"
          }
        ]
      }
    }
  },
  "dataSources": {
    "ds_sync": {
      "type": "ds.search",
      "name": "Synchronized",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:device\" earliest=-2h\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(deviceName) as name latest(deviceType) as type latest(model) as model latest(siteName) as site latest(status) as status latest(configStatus) as configStatus latest(firmwareVersion) as firmware latest(lastSeenAt) as lastSeenAt by serialNumber\n| eval config=if(isnull(configStatus) OR configStatus=\"\" OR configStatus=\"null\",\"(not reported)\",configStatus)\n| eval firmware=if(isnull(firmware) OR firmware=\"\" OR firmware=\"null\",\"(not reported)\",firmware), lastSeenAt=if(isnull(lastSeenAt) OR lastSeenAt=\"\" OR lastSeenAt=\"null\",\"(not reported)\",lastSeenAt)\n| where config=\"Synchronized\" | stats count"
      }
    },
    "ds_out": {
      "type": "ds.search",
      "name": "Not synchronized",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:device\" earliest=-2h\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(deviceName) as name latest(deviceType) as type latest(model) as model latest(siteName) as site latest(status) as status latest(configStatus) as configStatus latest(firmwareVersion) as firmware latest(lastSeenAt) as lastSeenAt by serialNumber\n| eval config=if(isnull(configStatus) OR configStatus=\"\" OR configStatus=\"null\",\"(not reported)\",configStatus)\n| eval firmware=if(isnull(firmware) OR firmware=\"\" OR firmware=\"null\",\"(not reported)\",firmware), lastSeenAt=if(isnull(lastSeenAt) OR lastSeenAt=\"\" OR lastSeenAt=\"null\",\"(not reported)\",lastSeenAt)\n| where config!=\"Synchronized\" AND config!=\"(not reported)\" | stats count"
      }
    },
    "ds_nr": {
      "type": "ds.search",
      "name": "Not reported",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:device\" earliest=-2h\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(deviceName) as name latest(deviceType) as type latest(model) as model latest(siteName) as site latest(status) as status latest(configStatus) as configStatus latest(firmwareVersion) as firmware latest(lastSeenAt) as lastSeenAt by serialNumber\n| eval config=if(isnull(configStatus) OR configStatus=\"\" OR configStatus=\"null\",\"(not reported)\",configStatus)\n| eval firmware=if(isnull(firmware) OR firmware=\"\" OR firmware=\"null\",\"(not reported)\",firmware), lastSeenAt=if(isnull(lastSeenAt) OR lastSeenAt=\"\" OR lastSeenAt=\"null\",\"(not reported)\",lastSeenAt)\n| where config=\"(not reported)\" | stats count"
      }
    },
    "ds_type": {
      "type": "ds.search",
      "name": "By type",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:device\" earliest=-2h\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(deviceName) as name latest(deviceType) as type latest(model) as model latest(siteName) as site latest(status) as status latest(configStatus) as configStatus latest(firmwareVersion) as firmware latest(lastSeenAt) as lastSeenAt by serialNumber\n| eval config=if(isnull(configStatus) OR configStatus=\"\" OR configStatus=\"null\",\"(not reported)\",configStatus)\n| eval firmware=if(isnull(firmware) OR firmware=\"\" OR firmware=\"null\",\"(not reported)\",firmware), lastSeenAt=if(isnull(lastSeenAt) OR lastSeenAt=\"\" OR lastSeenAt=\"null\",\"(not reported)\",lastSeenAt)\n| chart count over type by config"
      }
    },
    "ds_list": {
      "type": "ds.search",
      "name": "Devices",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:device\" earliest=-2h\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(deviceName) as name latest(deviceType) as type latest(model) as model latest(siteName) as site latest(status) as status latest(configStatus) as configStatus latest(firmwareVersion) as firmware latest(lastSeenAt) as lastSeenAt by serialNumber\n| eval config=if(isnull(configStatus) OR configStatus=\"\" OR configStatus=\"null\",\"(not reported)\",configStatus)\n| eval firmware=if(isnull(firmware) OR firmware=\"\" OR firmware=\"null\",\"(not reported)\",firmware), lastSeenAt=if(isnull(lastSeenAt) OR lastSeenAt=\"\" OR lastSeenAt=\"null\",\"(not reported)\",lastSeenAt)\n| where \"$cfg$\"=\"*\" OR config=\"$cfg$\"\n| eval Last_seen=lastSeenAt\n| table serialNumber name type model site status config firmware Last_seen\n| eval sortkey=case(config=\"Synchronized\",2,config=\"(not reported)\",3,true(),1)\n| sort 0 sortkey type site name\n| fields - sortkey\n| rename name as Name, type as Type, model as Model, site as Site, status as Status, config as \"Config status\", firmware as Firmware, Last_seen as \"Last seen\""
      }
    },
    "ds_chg": {
      "type": "ds.search",
      "name": "Changes and admin logins",
      "options": {
        "query": "`aruba_syslog` (\"Configuration change\" OR \"Accepted password\" OR \"has logged in\" OR \"commit\")\n| `aruba_syslog_fields`\n| eval User=coalesce(user,\"\")\n| sort - _time\n| eval Time=strftime(_time,\"%Y-%m-%d %H:%M:%S\")\n| table Time aruba_device aruba_process User aruba_message\n| rename aruba_device as Device, aruba_process as Process, aruba_message as Message"
      }
    }
  },
  "visualizations": {
    "v_sync": {
      "type": "splunk.singlevalue",
      "title": "Synchronized",
      "dataSources": {
        "primary": "ds_sync"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(cfg)"
      },
      "context": {
        "cfg": [
          {
            "value": "#53A051"
          }
        ]
      }
    },
    "v_out": {
      "type": "splunk.singlevalue",
      "title": "Not synchronized",
      "dataSources": {
        "primary": "ds_out"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "backgroundColor": "> majorValue | rangeValue(cfg)",
        "majorColor": "#FFFFFF",
        "unitColor": "#FFFFFF",
        "trendColor": "#FFFFFF",
        "sparklineStrokeColor": "#FFFFFF"
      },
      "context": {
        "cfg": [
          {
            "value": "#53A051",
            "to": 1
          },
          {
            "value": "#D99B1E",
            "from": 1
          }
        ]
      }
    },
    "v_nr": {
      "type": "splunk.singlevalue",
      "title": "Config status not reported",
      "dataSources": {
        "primary": "ds_nr"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(cfg)"
      },
      "context": {
        "cfg": [
          {
            "value": "#708794"
          }
        ]
      }
    },
    "v_type": {
      "type": "splunk.column",
      "title": "Config status by device type (click to filter)",
      "dataSources": {
        "primary": "ds_type"
      },
      "options": {
        "legendDisplay": "right",
        "x": "> primary | seriesByName('type')",
        "y": "> primary | frameBySeriesTypes('number')",
        "stackMode": "stacked",
        "seriesColorsByField": {
          "Synchronized": "#53A051",
          "(not reported)": "#708794",
          "Out of sync": "#DC4E41",
          "Not synchronized": "#DC4E41"
        }
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "cfg",
                "key": "name"
              }
            ]
          }
        }
      ]
    },
    "v_list": {
      "type": "splunk.table",
      "title": "Devices (click a row for its Central events and syslog)",
      "dataSources": {
        "primary": "ds_list"
      },
      "options": {
        "count": 10,
        "columnFormat": {
          "Config status": {
            "rowBackgroundColors": "> table | seriesByName(\"Config status\") | matchValue(m0)",
            "rowColors": "> table | seriesByName(\"Config status\") | matchValue(m0t)"
          },
          "Status": {
            "rowBackgroundColors": "> table | seriesByName(\"Status\") | matchValue(m1)",
            "rowColors": "> table | seriesByName(\"Status\") | matchValue(m1t)"
          }
        }
      },
      "context": {
        "m0": [
          {
            "match": "Synchronized",
            "value": "#53A051"
          },
          {
            "match": "(not reported)",
            "value": "transparent"
          },
          {
            "match": "Out of sync",
            "value": "#DC4E41"
          },
          {
            "value": "transparent"
          }
        ],
        "m0t": [
          {
            "match": "Synchronized",
            "value": "#FFFFFF"
          },
          {
            "match": "(not reported)",
            "value": "#FFFFFF"
          },
          {
            "match": "Out of sync",
            "value": "#FFFFFF"
          },
          {
            "value": "#FFFFFF"
          }
        ],
        "m1": [
          {
            "match": "ONLINE",
            "value": "#53A051"
          },
          {
            "match": "OFFLINE",
            "value": "#DC4E41"
          },
          {
            "value": "transparent"
          }
        ],
        "m1t": [
          {
            "match": "ONLINE",
            "value": "#FFFFFF"
          },
          {
            "match": "OFFLINE",
            "value": "#FFFFFF"
          },
          {
            "value": "#FFFFFF"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "type": "custom",
            "query": "(`aruba_central_index` serialNumber=\"$row.serialNumber.value$\") OR (`aruba_syslog` \"$row.Name.value$\")\n| table _time index sourcetype host status deviceName _raw",
            "earliest": "$tr.earliest$",
            "latest": "$tr.latest$",
            "newTab": true
          }
        }
      ]
    },
    "v_chg": {
      "type": "splunk.table",
      "title": "Syslog: configuration changes and admin logins (click for the raw events)",
      "dataSources": {
        "primary": "ds_chg"
      },
      "options": {
        "count": 6,
        "columnFormat": {
          "Message": {
            "width": 600
          }
        }
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "type": "custom",
            "query": "`aruba_syslog` | `aruba_syslog_fields` | search aruba_device=\"$row.Device.value$\" OR aruba_ap=\"$row.Device.value$\"",
            "earliest": "$tr.earliest$",
            "latest": "$tr.latest$",
            "newTab": true
          }
        }
      ]
    },
    "v_note": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "`configStatus` comes from the Inventory input (hourly by default). *Not reported* is common for gateways and for devices that are offline. Switches and gateways that are not synchronized are the ones to check first after a migration or a configuration change in New Central. Local changes and admin logins on gateways show up in Aruba syslog (processes `cfgm` and `sshd`).",
        "fontSize": "small"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$tr.earliest$",
            "latest": "$tr.latest$"
          }
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_time",
      "input_site",
      "input_cfg"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "type": "grid",
        "options": {
          "width": 1200
        },
        "structure": [
          {
            "item": "v_sync",
            "type": "block",
            "position": {
              "x": 0,
              "y": 0,
              "w": 400,
              "h": 140
            }
          },
          {
            "item": "v_out",
            "type": "block",
            "position": {
              "x": 400,
              "y": 0,
              "w": 400,
              "h": 140
            }
          },
          {
            "item": "v_nr",
            "type": "block",
            "position": {
              "x": 800,
              "y": 0,
              "w": 400,
              "h": 140
            }
          },
          {
            "item": "v_type",
            "type": "block",
            "position": {
              "x": 0,
              "y": 140,
              "w": 1200,
              "h": 280
            }
          },
          {
            "item": "v_list",
            "type": "block",
            "position": {
              "x": 0,
              "y": 420,
              "w": 1200,
              "h": 420
            }
          },
          {
            "item": "v_chg",
            "type": "block",
            "position": {
              "x": 0,
              "y": 840,
              "w": 1200,
              "h": 280
            }
          },
          {
            "item": "v_note",
            "type": "block",
            "position": {
              "x": 0,
              "y": 1120,
              "w": 1200,
              "h": 80
            }
          }
        ]
      }
    },
    "options": {
      "submitButton": false
    },
    "tabs": {
      "items": [
        {
          "layoutId": "layout_1",
          "label": "Config sync"
        }
      ]
    }
  }
}
